def _bootstrap(values: list[float], quantiles: tuple[int, ...]) -> list[float]:
    rng = random.Random(BOOTSTRAP_SEED)
    means = sorted(sum(values[rng.randrange(INSTANCES)] for _ in range(INSTANCES)) / INSTANCES
